<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:9px;margin:28px}h1{color:#172554;margin:0 0 5px;font-size:25px}.muted{color:#64748b}.hero{background:#172554;color:white;padding:20px;border-radius:10px;margin-bottom:16px}.summary{display:flex;gap:9px;margin-bottom:15px}.card{flex:1;background:#f1f5f9;padding:11px;border-radius:7px}.label{color:#64748b;font-size:8px;text-transform:uppercase}.value{font-size:16px;font-weight:bold;margin-top:6px}table{width:100%;border-collapse:collapse}th{background:#312e81;color:white;text-align:left;padding:7px}td{padding:7px;border-bottom:1px solid #e2e8f0;vertical-align:top}.num{text-align:right}.status{font-weight:bold;color:#4338ca}</style></head><body><div class="hero"><h1 style="color:white">Orders Report</h1><div>Generated {{ now()->format('M d, Y H:i') }} &middot; Amanelle Shop</div></div><div class="summary"><div class="card"><div class="label">Total orders</div><div class="value">{{ $orders->count() }}</div></div><div class="card"><div class="label">Total sales</div><div class="value">${{ number_format($orders->sum('total'), 2) }}</div></div><div class="card"><div class="label">Delivered</div><div class="value">{{ $orders->where('status', 'delivered')->count() }}</div></div><div class="card"><div class="label">Pending / active</div><div class="value">{{ $orders->whereNotIn('status', ['delivered', 'cancelled'])->count() }}</div></div></div><table><thead><tr><th>Order</th><th>Placed</th><th>Status</th><th>Customer</th><th>Contact</th><th>Delivery</th><th class="num">Total</th><th>Items</th></tr></thead><tbody>@foreach($orders as $order)<tr><td><b>{{ $order->number }}</b></td><td>{{ $order->placed_at?->format('Y-m-d H:i') }}</td><td class="status">{{ ucfirst($order->status) }}</td><td>{{ $order->customer_name }}</td><td>{{ $order->customer_phone }}<br>{{ $order->customer_email }}</td><td>{{ $order->city }}<br>{{ $order->shipping_address }}</td><td class="num"><b>${{ number_format($order->total, 2) }}</b></td><td>@foreach($order->items as $item){{ $item->quantity }}x {{ $item->product_name }} ({{ $item->variant_label }})@if(!$loop->last)<br>@endif @endforeach</td></tr>@endforeach</tbody></table></body></html>
